-- 33: POST-FLIGHT for the website migration 20261116100000_bottle_signs. Read-only.
-- ONE result set. Every row before the fingerprints must say ok = true. The FINGERPRINT rows give an md5 of each new function's body in the detail column (ok is always true there): compare them with
-- the same query on a replay of the repository (tests/db/run.sh database); they must be identical.
select * from (
  select 1 as n, 'the 8 function(s) exist' as check_name,
         (select count(*) = 8 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['venue_sign_settings', 'save_venue_sign_settings', 'set_bottle_sign_eligible', 'desk_set_bottle_sign', 'desk_review_bottle_sign', 'desk_line_signs', 'desk_pending_sign_reviews', 'bottle_sign_service_gate'])) as ok,
         (select string_agg(p.proname, ', ' order by p.proname) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['venue_sign_settings', 'save_venue_sign_settings', 'set_bottle_sign_eligible', 'desk_set_bottle_sign', 'desk_review_bottle_sign', 'desk_line_signs', 'desk_pending_sign_reviews', 'bottle_sign_service_gate'])) as detail
  union all
  select 2, 'the app-facing functions (and any trigger function meant to) run with their owner''s rights and a fixed search path',
         (select bool_and(p.prosecdef and coalesce(p.proconfig::text, '') like '%search_path=public%') from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['venue_sign_settings', 'save_venue_sign_settings', 'set_bottle_sign_eligible', 'desk_set_bottle_sign', 'desk_review_bottle_sign', 'desk_line_signs', 'desk_pending_sign_reviews', 'bottle_sign_service_gate'])),
         (select string_agg(p.proname || '=' || p.prosecdef || ' ' || coalesce(p.proconfig::text, 'no path'), '; ' order by p.proname) from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['venue_sign_settings', 'save_venue_sign_settings', 'set_bottle_sign_eligible', 'desk_set_bottle_sign', 'desk_review_bottle_sign', 'desk_line_signs', 'desk_pending_sign_reviews', 'bottle_sign_service_gate']))
  union all
  select 3, 'signed-in people (and the service role) can call the app-facing functions; visitors cannot (the database checks who may do what inside)',
         (has_function_privilege('authenticated', 'public.venue_sign_settings(uuid)', 'execute') and has_function_privilege('service_role', 'public.venue_sign_settings(uuid)', 'execute') and not has_function_privilege('anon', 'public.venue_sign_settings(uuid)', 'execute') and has_function_privilege('authenticated', 'public.save_venue_sign_settings(uuid, jsonb)', 'execute') and has_function_privilege('service_role', 'public.save_venue_sign_settings(uuid, jsonb)', 'execute') and not has_function_privilege('anon', 'public.save_venue_sign_settings(uuid, jsonb)', 'execute') and has_function_privilege('authenticated', 'public.set_bottle_sign_eligible(uuid, uuid, boolean)', 'execute') and has_function_privilege('service_role', 'public.set_bottle_sign_eligible(uuid, uuid, boolean)', 'execute') and not has_function_privilege('anon', 'public.set_bottle_sign_eligible(uuid, uuid, boolean)', 'execute') and has_function_privilege('authenticated', 'public.desk_set_bottle_sign(uuid, text)', 'execute') and has_function_privilege('service_role', 'public.desk_set_bottle_sign(uuid, text)', 'execute') and not has_function_privilege('anon', 'public.desk_set_bottle_sign(uuid, text)', 'execute') and has_function_privilege('authenticated', 'public.desk_review_bottle_sign(uuid, text, text)', 'execute') and has_function_privilege('service_role', 'public.desk_review_bottle_sign(uuid, text, text)', 'execute') and not has_function_privilege('anon', 'public.desk_review_bottle_sign(uuid, text, text)', 'execute') and has_function_privilege('authenticated', 'public.desk_line_signs(uuid[])', 'execute') and has_function_privilege('service_role', 'public.desk_line_signs(uuid[])', 'execute') and not has_function_privilege('anon', 'public.desk_line_signs(uuid[])', 'execute') and has_function_privilege('authenticated', 'public.desk_pending_sign_reviews(uuid)', 'execute') and has_function_privilege('service_role', 'public.desk_pending_sign_reviews(uuid)', 'execute') and not has_function_privilege('anon', 'public.desk_pending_sign_reviews(uuid)', 'execute')),
         'venue_sign_settings, save_venue_sign_settings, set_bottle_sign_eligible, desk_set_bottle_sign, desk_review_bottle_sign, desk_line_signs, desk_pending_sign_reviews'
  union all
  select 4, 'every club starts with signs off and no approval, no bottle is a sign bottle and no order carries a sign (nothing existing was changed)',
         ((select count(*) = 0 from public.site_venues where sign_mode <> 'off' or sign_review) and (select count(*) = 0 from public.site_bottles where sign_eligible) and (select count(*) = 0 from public.site_table_booking_bottles where sign_text is not null or sign_status is not null)),
         (select count(*)::text from public.site_venues where sign_mode = 'off' and not sign_review) || ' of ' || (select count(*)::text from public.site_venues) || ' clubs on the defaults'
  union all
  select 5, 'the review-before-service trigger is on the bottle lines table, and the constraints that keep a sign tidy are in place',
         (exists (select 1 from pg_trigger g where g.tgname = 'site_table_booking_bottles_sign_gate' and g.tgrelid = 'public.site_table_booking_bottles'::regclass and not g.tgisinternal) and exists (select 1 from pg_constraint c where c.conrelid = 'public.site_table_booking_bottles'::regclass and c.conname in ('site_tbb_sign_text_check')) and exists (select 1 from pg_constraint c where c.conrelid = 'public.site_table_booking_bottles'::regclass and c.conname = 'site_tbb_sign_together') and exists (select 1 from pg_constraint c where c.conrelid = 'public.site_venues'::regclass and c.conname = 'site_venues_sign_mode_check')),
         'trigger + 4 checks'
  union all
  select 6, 'the person columns of a sign do not block deleting an account (ON DELETE SET NULL)',
         ((select count(*) = 2 and bool_and(c.confdeltype = 'n') from pg_constraint c where c.conrelid = 'public.site_table_booking_bottles'::regclass and c.contype = 'f' and c.confrelid = 'auth.users'::regclass and exists (select 1 from pg_attribute a where a.attrelid = c.conrelid and a.attnum = any (c.conkey) and a.attname in ('sign_set_by', 'sign_reviewed_by')))),
         'sign_set_by, sign_reviewed_by'
  union all
  select 6 + row_number() over (order by p.proname)::int, 'FINGERPRINT ' || p.proname, true,
         md5(regexp_replace(p.prosrc, '\s+', ' ', 'g') || '|' || p.prosecdef::text || '|' || coalesce(p.proconfig::text, '') || '|' || pg_get_function_result(p.oid))
    from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any (array['venue_sign_settings', 'save_venue_sign_settings', 'set_bottle_sign_eligible', 'desk_set_bottle_sign', 'desk_review_bottle_sign', 'desk_line_signs', 'desk_pending_sign_reviews', 'bottle_sign_service_gate'])
) r order by n;
